      fr: "Cette vaste chaîne de montagnes à la frontière avec l'Allemagne et l'Autriche constitue l'un des plus grands massifs forestiers d'un seul tenant en Europe centrale. Elle abrite de nombreux lacs glaciaires et tourbières.",
