    imageHint: "Macha lake beach pine forest",
    image: "/poi-images/czechrepublic-macha-lake-nature-v2.webp",
    descriptionAdvanced: {
      de: "Der Máchasee (Máchovo jezero) ist eigentlich kein natürlicher See, sondern ein großer Fischteich, der im 14. Jahrhundert auf Anweisung von Kaiser Karl IV. angelegt wurde. Mit einer Fläche von 284 Hektar ist er der größte Teich in Nordböhmen und ein äußerst beliebtes Erholungsgebiet. Seinen Namen erhielt er erst im 20. Jahrhundert zu Ehren des romantischen Dichters Karel Hynek Mácha, der von der Region zu seinem berühmten Gedicht 'Mai' inspiriert wurde. Der See hat zwei kleine Inseln, die Mauseinsel (Myší ostrov) und die Enteninsel (Kachní ostrov), die als ornithologische Schutzgebiete dienen. Die Umgebung des Sees ist geprägt von Sandstränden, Kiefernwäldern und bizarren Sandsteinformationen. Die Städte Doksy und Staré Splavy an seinen Ufern bieten eine umfassende touristische Infrastruktur mit Hotels, Campingplätzen und Restaurants. Der Máchasee ist ein Zentrum für Wassersport, Wandern und Radfahren und zieht jährlich Tausende von Besuchern an.",
      hu: "A Mácha-tó (Máchovo jezero) valójában nem természetes tó, hanem egy nagy halastó, amelyet a 14. században IV. Károly császár utasítására hoztak létre. 284 hektáros területével Észak-Csehország legnagyobb tava és rendkívül népszerű üdülőterület. Nevét csak a 20. században kapta a romantikus költő, Karel Hynek Mácha tiszteletére, akit a régió ihletett a híres 'Május' című költeményére. A tónak két kis szigete van, az Egér-sziget (Myší ostrov) és a Kacsa-sziget (Kachní ostrov), amelyek madártani védett területek. A tó környékét homokos strandok, fenyőerdők és bizarr homokkő képződmények jellemzik. A partján fekvő Doksy és Staré Splavy városok teljes körű turisztikai infrastruktúrát kínálnak szállodákkal, kempingekkel és éttermekkel. A Mácha-tó a vízi sportok, a túrázás és a kerékpározás központja, és évente több ezer látogatót vonz.",
      ro: "Lacul Mácha (Máchovo jezero) nu este, de fapt, un lac natural, ci un iaz mare de pește, creat în secolul al XIV-lea la ordinul împăratului Carol al IV-lea. Cu o suprafață de 284 de hectare, este cel mai mare iaz din Boemia de Nord și o zonă de agrement extrem de populară. Și-a primit numele abia în secolul al XX-lea, în onoarea poetului romantic Karel Hynek Mácha, care a fost inspirat de regiune pentru faimosul său poem 'Mai'. Lacul are două insule mici, Insula Șoarecelui (Myší ostrov) și Insula Raței (Kachní ostrov), care servesc drept rezervații ornitologice. Împrejurimile lacului sunt caracterizate de plaje cu nisip, păduri de pini și formațiuni bizare de gresie. Orașele Doksy și Staré Splavy de pe malurile sale oferă o infrastructură turistică completă, cu hoteluri, campinguri și restaurante. Lacul Mácha este un centru pentru sporturi nautice, drumeții și ciclism, atrăgând mii de vizitatori în fiecare an.",
      en: "Mácha's Lake (Máchovo jezero) is not actually a natural lake, but a large fishpond established in the 14th century by order of Emperor Charles IV. With an area of 284 hectares, it is the largest pond in North Bohemia and an extremely popular recreational area. It was named only in the 20th century in honor of the romantic poet Karel Hynek Mácha, who was inspired by the region for his famous poem 'May'. The lake has two small islands, Mouse Island (Myší ostrov) and Duck Island (Kachní ostrov), which serve as ornithological sanctuaries. The surroundings of the lake are characterized by sandy beaches, pine forests, and bizarre sandstone formations. The towns of Doksy and Staré Splavy on its shores offer a comprehensive tourist infrastructure with hotels, campsites, and restaurants. Mácha's Lake is a center for water sports, hiking, and cycling, attracting thousands of visitors every year.",
      es: "El Lago de Mácha (Máchovo jezero) no es un lago natural, sino un gran estanque de peces creado en el siglo XIV por instrucción del emperador Carlos IV. Con una superficie de 284 hectáreas, es el estanque más grande del norte de Bohemia y un área de recreo sumamente popular. Recibió su nombre actual en el siglo XX en honor al poeta romántico Karel Hynek Mácha, quien se inspiró en la región para su famoso poema 'Mayo'. El lago cuenta con dos pequeñas islas, la Isla de los Ratones (Myší ostrov) y la Isla de los Patos (Kachní ostrov), que sirven como reservas ornitológicas. El entorno destaca por sus playas de arena, pinares y caprichosas formaciones de arenisca. Las ciudades de Doksy y Staré Splavy en sus orillas ofrecen una completa infraestructura turística con hoteles, campings y restaurantes. El Lago de Mácha es un centro para deportes acuáticos, senderismo y ciclismo que atrae a miles de visitantes anualmente.",
      pt: "O Lago de Mácha (Máchovo jezero) não é, na verdade, um lago natural, mas sim um grande tanque de peixes criado no século XIV por ordem do Imperador Carlos IV. Com uma área de 284 hectares, é o maior tanque do norte da Boêmia e uma área de lazer extremamente popular. Recebeu o seu nome apenas no século XX em honra do poeta romântico Karel Hynek Mácha, que se inspirou na região para o seu famoso poema 'Maio'. O lago tem duas pequenas ilhas, a Ilha dos Ratos (Myší ostrov) e a Ilha dos Patos (Kachní ostrov), que servem como áreas de proteção ornitológica. Os arredores do lago são caracterizados por praias de areia, florestas de pinheiros e formações bizarras de arenito. As cidades de Doksy e Staré Splavy nas suas margens oferecem uma infraestrutura turística abrangente com hotéis, parques de campismo e restaurantes. O Máchovo jezero é um centro para desportos náuticos, caminhadas e ciclismo, atraindo milhares de visitantes anualmente.",
      fr: "Le lac de Mácha (Máchovo jezero) n'est pas un lac naturel, mais un immense étang de pisciculture aménagé au XIVe siècle sous les ordres de l'empereur Charles IV. Couvrant 284 hectares, c'est le plus grand étang de Bohême du Nord et un lieu de villégiature incontournable. Il doit son nom moderne au poète romantique Karel Hynek Mácha, qui y trouva l'inspiration pour son célèbre poème 'Mai'. Le lac abrite deux petites îles, l'île aux Souris (Myší ostrov) et l'île aux Canards (Kachní ostrov), classées réserves ornithologiques. Ses rives alternent entre plages de sable fin, forêts de pins et formations rocheuses de grès. Les villes de Doksy et Staré Splavy offrent une infrastructure touristique complète avec hôtels, campings et restaurants. Destination phare pour les sports nautiques, la randonnée et le cyclisme, le lac de Mácha attire chaque année des milliers de visiteurs.",
    },
