    imageHint: "Hranice abyss water hole cave",
    image: "/poi-images/czechrepublic-hranice-abyss-nature-v2.webp",
    descriptionAdvanced: {
      de: "Der Hranice-Abgrund (Hranická propast) ist ein außergewöhnliches Naturphänomen in der Nähe der Stadt Hranice. Es handelt sich um die tiefste überflutete Süßwasserhöhle der Welt. Während die Tiefe des trockenen Teils nur 69,5 Meter beträgt, wurde die Gesamttiefe des überfluteten Teils im Jahr 2016 von einem ferngesteuerten Unterwasserfahrzeug auf erstaunliche 404 Meter vermessen, ohne dass der Grund erreicht wurde. Wissenschaftler vermuten, dass die tatsächliche Tiefe 800 bis 1200 Meter betragen könnte. Die Entstehung der Schlucht ist einzigartig: Sie wurde nicht wie die meisten Karsthöhlen von oben durch Regenwasser, sondern von unten durch stark kohlensäurehaltiges, warmes Mineralwasser geformt, das aus großer Tiefe aufstieg und das Kalkgestein auflöste. Aufgrund der hohen Konzentration von Kohlendioxid am Grund ist der direkte Zugang zur Schlucht für die Öffentlichkeit aus Sicherheitsgründen gesperrt, aber ein Aussichtspunkt am Rand bietet einen sicheren Blick in die Tiefe.",
      hu: "A Hranicei-szakadék (Hranická propast) egy rendkívüli természeti jelenség Hranice városa közelében. Ez a világ legmélyebb elárasztott édesvízi barlangja. Míg a száraz rész mélysége mindössze 69,5 méter, az elárasztott rész teljes mélységét 2016-ban egy távirányítású víz alatti jármű elképesztő 404 méterben mérte, anélkül, hogy elérte volna a feneket. A tudósok úgy vélik, hogy a tényleges mélység 800-1200 méter is lehet. A szakadék keletkezése egyedülálló: nem felülről, esővíz által alakult ki, mint a legtöbb karsztbarlang, hanem alulról, erősen szénsavas, meleg ásványvíz által, amely nagy mélységből tört fel és oldotta fel a mészkövet. Az alján lévő magas szén-dioxid-koncentráció miatt a szakadékba való közvetlen belépés biztonsági okokból tilos a nyilvánosság számára, de a peremén lévő kilátópont biztonságos betekintést nyújt a mélybe.",
      ro: "Prăpastia Hranice (Hranická propast) este un fenomen natural extraordinar în apropierea orașului Hranice. Este cea mai adâncă peșteră de apă dulce inundată din lume. În timp ce adâncimea părții uscate este de numai 69,5 metri, adâncimea totală a părții inundate a fost măsurată în 2016 de un vehicul subacvatic teleghidat la uluitoarea adâncime de 404 metri, fără a atinge fundul. Oamenii de știință speculează că adâncimea reală ar putea fi între 800 și 1200 de metri. Geneza prăpastiei este unică: nu a fost formată de sus de apa de ploaie, ca majoritatea peșterilor carstice, ci de jos, de ape minerale calde, puternic carbonatate, care au urcat din adâncuri și au dizolvat calcarul. Din cauza concentrației ridicate de dioxid de carbon la bază, accesul direct în prăpastie este interzis publicului din motive de siguranță, dar un punct de belvedere de pe margine oferă o privire sigură în adâncuri.",
      en: "The Hranice Abyss (Hranická propast) is an extraordinary natural phenomenon near the town of Hranice. It is the deepest flooded freshwater cave in the world. While the depth of the dry part is only 69.5 meters, the total depth of the flooded part was measured in 2016 by a remote-operated underwater vehicle at an astonishing 404 meters, without reaching the bottom. Scientists speculate that the actual depth could be between 800 and 1200 meters. The genesis of the abyss is unique: it was not formed from above by rainwater like most karst caves, but from below by highly carbonated warm mineral water that rose from great depths and dissolved the limestone. Due to the high concentration of carbon dioxide at the bottom, direct access to the abyss is forbidden to the public for safety reasons, but a viewpoint on the edge offers a safe look into the depths.",
      es: "El abismo de Hranice (Hranická propast) es un fenómeno natural extraordinario cerca de la ciudad de Hranice. Se trata de la cueva de agua dulce inundada más profunda del planeta. Aunque la profundidad de la parte seca es de solo 69,5 metros, en 2016 un vehículo submarino operado por control remoto midió una profundidad de 404 metros en la parte inundada sin llegar al fondo. Los científicos estiman que la profundidad real podría estar entre 800 y 1.200 metros. El origen de la sima es único: no se formó de arriba hacia abajo por el agua de lluvia, como la mayoría de las cuevas kársticas, sino de abajo hacia arriba por agua mineral caliente y rica en dióxido de carbono que ascendió desde las profundidades disolviendo la roca caliza. Debido a la alta concentración de CO2 en el fondo, el acceso directo está cerrado al público por seguridad, pero un mirador en el borde ofrece una vista segura del abismo.",
      pt: "O Abismo de Hranice (Hranická propast) é um fenómeno natural extraordinário perto da cidade de Hranice. Trata-se da caverna de água doce inundada mais profunda do mundo. Enquanto a profundidade da parte seca é de apenas 69,5 metros, a profundidade total da parte inundada foi medida em 2016 por um veículo subaquático controlado remotamente em impressionantes 404 metros, sem que o fundo fosse alcançado. Os cientistas suspeitam que a profundidade real possa ser de 800 a 1200 metros. A formação do abismo é única: não foi formado de cima para baixo pela água da chuva, como a maioria das cavernas cársicas, mas de baixo para cima por água mineral quente e rica em dióxido de carbono, que subiu de grande profundidade e dissolveu a rocha calcária. Devido à alta concentração de dióxido de carbono no fundo, o acesso direto ao abismo está fechado ao público por razões de segurança, mas um miradouro na borda oferece uma vista segura para as profundezas.",
      fr: "L'abîme de Hranice (Hranická propast) est un phénomène naturel exceptionnel situé près de la ville de Hranice. C'est la grotte d'eau douce immergée la plus profonde du monde. Si la partie sèche ne mesure que 69,5 mètres, la profondeur de la partie inondée a été mesurée en 2016 par un robot sous-marin à 404 mètres, sans pour autant atteindre le fond. Les scientifiques estiment que la profondeur réelle pourrait se situer entre 800 et 1 200 mètres. Sa formation est unique : contrairement à la plupart des grottes karstiques creusées par l'eau de pluie, cet abîme a été façonné par le bas, par des remontées d'eau minérale chaude et acide qui ont dissous le calcaire. En raison de la forte concentration de dioxyde de carbone au fond, l'accès direct est interdit au public, mais un point d'observation permet d'admirer la profondeur en toute sécurité.",
    },
    factsAdvanced: {
      de: ["Bestätigte Tiefe über 450 Meter", "Geologische Tiefe auf 1 km geschätzt", "Trockener Teil ist 69,5 m tief", "Besteht aus devonischem Kalkstein"],
      hu: ["Mért mélysége meghaladja a 450 métert", "Becsült geológiai mélysége 1 km", "Száraz részének mélysége 69,5 méter", "Devon időszaki mészkőből áll"],
      ro: ["Adâncime confirmată de peste 450 m", "Adâncime geologică estimată la 1 km", "Partea uscată are 69,5 m adâncime", "Formată din calcar devonian"],
      en: ["Confirmed depth over 450 meters", "Estimated geological depth of 1 km", "Dry part is 69.5 meters deep", "Composed of Devonian limestone"],
    },
