    imageHint: "Black Lake Sumava glacial mountain",
    image: "/poi-images/czechrepublic-cerne-jezero-nature-v2.webp",
    descriptionAdvanced: {
      de: "Der Černé jezero (Schwarzer See) ist der größte und tiefste natürliche See im Böhmerwald und in der gesamten Tschechischen Republik. Dieser Gletschersee, der während der letzten Eiszeit entstand, liegt auf einer Höhe von 1.008 Metern am Fuße des Jezerní hora (Seeberg). Seine maximale Tiefe erreicht beeindruckende 40,6 Meter. Der See verdankt seinen Namen der dunklen Farbe seines Wassers, die durch die Reflexion der umliegenden dichten Wälder und eine dicke Schicht von Schlamm am Grund, der aus abgelagertem Pollen von Nadelbäumen besteht, verursacht wird. Der See und seine Umgebung sind Teil des Nationalen Naturreservats Schwarzer und Teufelssee. Vom See aus fließt der Černý potok (Schwarzbach) ins Tal. Ein besonderes technisches Denkmal ist das 1929-1930 erbaute Pumpspeicherkraftwerk, das den See als oberes Reservoir nutzt. Der See ist ein beliebtes Wanderziel, obwohl das Schwimmen zum Schutz des einzigartigen Ökosystems verboten ist.",
      hu: "A Černé jezero (Fekete-tó) a Šumava és egész Csehország legnagyobb és legmélyebb természetes tava. Ez a gleccsertó, amely az utolsó jégkorszakban keletkezett, 1008 méteres magasságban fekszik a Jezerní hora (Tó-hegy) lábánál. Maximális mélysége eléri a lenyűgöző 40,6 métert. A tó a nevét a vizének sötét színéről kapta, amelyet a környező sűrű erdők tükröződése és a fenyőfákról lerakódott pollenből álló vastag iszapréteg okoz a tó fenekén. A tó és környéke a Fekete- és Ördög-tó Nemzeti Természeti Rezervátum része. A tóból a Černý potok (Fekete-patak) folyik a völgybe. Különleges műszaki emlék az 1929-1930-ban épült szivattyús-tározós vízerőmű, amely a tavat felső víztározóként használja. A tó népszerű túracélpont, bár az egyedülálló ökoszisztéma védelme érdekében a fürdés tilos.",
      ro: "Černé jezero (Lacul Negru) este cel mai mare și cel mai adânc lac natural din Munții Šumava și din întreaga Republică Cehă. Acest lac glaciar, format în timpul ultimei ere glaciare, este situat la o altitudine de 1.008 metri, la poalele muntelui Jezerní hora. Adâncimea sa maximă atinge o valoare impresionantă de 40,6 metri. Lacul își datorează numele culorii întunecate a apei sale, cauzată de reflexia pădurilor dense din jur și de un strat gros de nămol pe fund, format din polen depus de la conifere. Lacul și împrejurimile sale fac parte din Rezervația Naturală Națională Lacurile Negru și Diavolului. Din lac, pârâul Černý potok (Pârâul Negru) curge spre vale. Un monument tehnic special este hidrocentrala cu acumulare prin pompare, construită în 1929-1930, care folosește lacul ca rezervor superior. Lacul este o destinație populară pentru drumeții, deși înotul este interzis pentru a proteja ecosistemul unic.",
      en: "Černé jezero (Black Lake) is the largest and deepest natural lake in the Bohemian Forest and the entire Czech Republic. This glacial lake, formed during the last ice age, is located at an altitude of 1,008 meters at the foot of the Jezerní hora (Lake Mountain). Its maximum depth reaches an impressive 40.6 meters. The lake owes its name to the dark color of its water, which is caused by the reflection of the surrounding dense forests and a thick layer of sludge at the bottom, consisting of deposited pollen from coniferous trees. The lake and its surroundings are part of the Black and Devil's Lakes National Nature Reserve. The Černý potok (Black Brook) flows from the lake into the valley. A special technical monument is the pumped-storage hydroelectric power plant built in 1929-1930, which uses the lake as its upper reservoir. The lake is a popular hiking destination, although swimming is prohibited to protect the unique ecosystem.",
      es: "El Černé jezero (Lago Negro) es el lago natural más grande y profundo de la Selva de Bohemia y de toda la República Checa. Este lago glacial, formado durante la última glaciación, se sitúa a 1.008 metros de altitud al pie del Jezerní hora (Monte del Lago). Su profundidad máxima alcanza los impresionantes 40,6 metros. El lago debe su nombre al color oscuro de sus aguas, provocado por el reflejo de los densos bosques circundantes y una gruesa capa de lodo en el fondo, compuesta por polen sedimentado de coníferas. El lago y su entorno forman parte de la Reserva Natural Nacional de los Lagos Negro y del Diablo. Desde el lago fluye el arroyo Černý potok hacia el valle. Un monumento técnico destacado es la central de bombeo construida entre 1929 y 1930, que utiliza el lago como depósito superior. Es un destino popular para el senderismo, aunque el baño está prohibido para proteger su ecosistema único.",
      pt: "O Černé jezero (Lago Negro) é o maior e mais profundo lago natural na Selva da Boêmia e em toda a República Checa. Este lago glacial, que surgiu durante a última era glacial, situa-se a uma altitude de 1.008 metros no sopé do Jezerní hora. A sua profundidade máxima atinge impressionantes 40,6 metros. O lago deve o seu nome à cor escura da água, causada pelo reflexo das densas florestas circundantes e por uma espessa camada de lodo no fundo, composta por pólen depositado de coníferas. O lago e os seus arredores fazem parte da Reserva Natural Nacional dos Lagos Negro e do Diabo. A partir do lago, o ribeiro Černý potok corre para o vale. Um monumento técnico especial é a central hidroelétrica reversível construída entre 1929 e 1930, que utiliza o lago como reservatório superior. O lago é um destino de caminhadas popular, embora nadar seja proibido para proteger o ecossistema único.",
      fr: "Le Černé jezero (Lac Noir) est le plus grand et le plus profond lac naturel de la forêt de Bohême et de toute la République tchèque. Ce lac glaciaire, formé lors de la dernière période glaciaire, se situe à une altitude de 1 008 mètres au pied du Jezerní hora. Sa profondeur maximale atteint les 40,6 mètres. Le lac doit son nom à la couleur sombre de ses eaux, causée par le reflet des forêts denses environnantes et une épaisse couche de vase au fond, constituée de pollen de conifères sédimenté. Le lac et ses environs font partie de la réserve naturelle nationale des lacs Noir et du Diable. Le ruisseau Černý potok s'écoule du lac vers la vallée. Un monument technique remarquable est la centrale de pompage-turbinage construite en 1929-1930, qui utilise le lac comme réservoir supérieur. C'est une destination de randonnée prisée, bien que la baignade soit interdite pour protéger cet écosystème unique.",
    },
