    name: { de: "Lausitzer Gebirge", hu: "Luzsicei-hegység", ro: "Munții Lužické", en: "Lusatian Mountains"},
    image: "/poi-images/czechrepublic-lusatian-mountains-nature-v2.webp",
    coords: [14.65, 50.84],
    coords: [14.65, 50.84],
    description: {
      de: "Das Lausitzer Gebirge ist ein Mittelgebirge an der Grenze zu Deutschland. Es ist geprägt durch Vulkankegel, Sandsteinfelsen und malerische Dörfer mit traditioneller Volksarchitektur.",
      hu: "A Luzsicei-hegység egy középhegység a német határon. Vulkáni kúpok, homokkő sziklák és festői falvak jellemzik hagyományos népi építészettel.",
      ro: "Munții Lužické reprezintă un lanț muntos la granița cu Germania. Sunt caracterizați de conuri vulcanice, stânci de gresie și sate pitorești.",
      en: "The Lusatian Mountains are a mountain range on the border with Germany. They are characterized by volcanic cones, sandstone rocks, and picturesque villages with traditional folk architecture.",
      es: "Las Montañas de Lusacia son una cordillera media en la frontera con Alemania. Se caracterizan por sus conos volcánicos, rocas de arenisca y pueblos pintorescos con arquitectura tradicional.",
      pt: "As Montanhas da Lusácia são uma cordilheira média na fronteira com a Alemanha. Caracterizam-se por cones vulcânicos, rochas de arenito e aldeias pitorescas com arquitetura tradicional.",
      fr: "Les monts de Lusace forment un massif de moyenne montagne à la frontière allemande. Ils se distinguent par leurs cônes volcaniques, leurs falaises de grès et leurs villages à l'architecture traditionnelle.",
    },
