    imageHint: "Devils lake Sumava forest dark water",
    image: "/poi-images/czechrepublic-certovo-jezero-nature-v2.webp",
    descriptionAdvanced: {
      de: "Das Čertovo jezero (Teufelssee) ist ein weiterer beeindruckender Gletschersee im Böhmerwald (Šumava), nur etwa 2,5 Kilometer vom größeren Černé jezero (Schwarzer See) entfernt. Der See liegt auf einer Höhe von 1.030 Metern und ist mit einer maximalen Tiefe von 37 Metern der zweittiefste See des Gebirges. Umgeben von dichten Fichtenwäldern, hat sein Wasser eine geheimnisvolle, dunkle Atmosphäre, die durch den Schatten der 300 Meter hohen Felswand Jezerní stěna noch verstärkt wird. Der See ist Teil des Nationalen Naturreservats Schwarzer und Teufelssee. Eine Legende besagt, dass der Teufel hier ertrank, als er versuchte, die Seele eines Mädchens zu rauben, und sein Körper den See schuf. Eine geologische Besonderheit ist, dass der Teufelssee zur Donau-Wasserscheide gehört, während der nahe gelegene Schwarze See zur Elbe-Wasserscheide gehört. Ein malerischer Wanderweg verbindet die beiden Seen und bietet spektakuläre Ausblicke.",
      hu: "A Čertovo jezero (Ördög-tó) egy másik lenyűgöző gleccsertó a Šumavában, mindössze 2,5 kilométerre a nagyobb Černé jezero-tól (Fekete-tó). A tó 1030 méteres magasságban fekszik, és 37 méteres maximális mélységével a hegység második legmélyebb tava. Sűrű lucfenyőerdők veszik körül, vizének titokzatos, sötét hangulatát a 300 méter magas Jezerní stěna sziklafal árnyéka tovább fokozza. A tó a Fekete- és Ördög-tó Nemzeti Természeti Rezervátum része. Egy legenda szerint az ördög itt fulladt meg, amikor megpróbálta elrabolni egy lány lelkét, és a teste hozta létre a tavat. Geológiai különlegesség, hogy az Ördög-tó a Duna vízgyűjtőjéhez tartozik, míg a közeli Fekete-tó az Elba vízgyűjtőjéhez. Egy festői túraútvonal köti össze a két tavat, látványos kilátást nyújtva.",
      ro: "Čertovo jezero (Lacul Diavolului) este un alt lac glaciar impresionant din Munții Šumava, la doar aproximativ 2,5 kilometri de mai marele Černé jezero (Lacul Negru). Lacul este situat la o altitudine de 1.030 de metri și, cu o adâncime maximă de 37 de metri, este al doilea cel mai adânc lac din lanțul muntos. Înconjurat de păduri dense de molid, apa sa are o atmosferă misterioasă, întunecată, care este accentuată de umbra peretelui stâncos Jezerní stěna, înalt de 300 de metri. Lacul face parte din Rezervația Naturală Națională Lacurile Negru și Diavolului. O legendă spune că diavolul s-a înecat aici în timp ce încerca să fure sufletul unei fete, iar corpul său a creat lacul. O particularitate geologică este că Lacul Diavolului aparține bazinului hidrografic al Dunării, în timp ce Lacul Negru din apropiere aparține bazinului hidrografic al Elbei. O potecă pitorească de drumeție leagă cele două lacuri, oferind priveliști spectaculoase.",
      en: "Čertovo jezero (Devil's Lake) is another impressive glacial lake in the Bohemian Forest (Šumava), only about 2.5 kilometers from the larger Černé jezero (Black Lake). The lake is located at an altitude of 1,030 meters and, with a maximum depth of 37 meters, is the second deepest lake in the mountain range. Surrounded by dense spruce forests, its water has a mysterious, dark atmosphere, which is enhanced by the shadow of the 300-meter-high Jezerní stěna rock face. The lake is part of the Black and Devil's Lakes National Nature Reserve. A legend says that the devil drowned here while trying to steal a girl's soul, and his body created the lake. A geological peculiarity is that the Devil's Lake belongs to the Danube watershed, while the nearby Black Lake belongs to the Elbe watershed. A picturesque hiking trail connects the two lakes, offering spectacular views.",
      es: "El Čertovo jezero (Lago del Diablo) es otro impresionante lago glacial en la Selva de Bohemia (Šumava), a solo unos 2,5 kilómetros del mayor Černé jezero (Lago Negro). El lago se encuentra a 1.030 metros de altitud y, con una profundidad máxima de 37 metros, es el segundo más profundo de la cordillera. Rodeado de densos bosques de abetos, sus aguas tienen una atmósfera misteriosa y oscura, acentuada por la sombra de la pared rocosa de 300 metros de altura Jezerní stěna. El lago forma parte de la Reserva Natural Nacional de los Lagos Negro y del Diablo. Una leyenda cuenta que el diablo se ahogó aquí al intentar robar el alma de una joven, y su cuerpo creó el lago. Una particularidad geológica es que el Lago del Diablo pertenece a la cuenca del Danubio, mientras que el cercano Lago Negro pertenece a la cuenca del Elba. Una pintoresca ruta de senderismo conecta ambos lagos y ofrece vistas espectaculares.",
      pt: "O Čertovo jezero (Lago do Diabo) é outro impressionante lago glacial na Selva da Boêmia (Šumava), a apenas cerca de 2,5 quilómetros do maior Černé jezero (Lago Negro). O lago situa-se a uma altitude de 1.030 metros e, com uma profundidade máxima de 37 metros, é o segundo lago mais profundo da cordilheira. Rodeado por densas florestas de abetos, as suas águas têm uma atmosfera misteriosa e escura, reforçada pela sombra da parede rochosa de 300 metros de altura Jezerní stěna. O lago faz parte da Reserva Natural Nacional dos Lagos Negro e do Diabo. Uma lenda diz que o diabo se afogou aqui ao tentar roubar a alma de uma rapariga, e o seu corpo criou o lago. Uma característica geológica é que o Lago do Diabo pertence à bacia do Danúbio, enquanto o vizinho Lago Negro pertence à bacia do Elba. Um trilho pitoresco liga os dois lagos e oferece vistas espetaculares.",
      fr: "Le Čertovo jezero (Lac du Diable) est un autre lac glaciaire impressionnant de la forêt de Bohême (Šumava), situé à environ 2,5 kilomètres du grand Černé jezero (Lac Noir). Perché à 1 030 mètres d'altitude, il est, avec ses 37 mètres de fond, le deuxième lac le plus profond du massif. Entouré de forêts d'épicéas, ses eaux dégagent une atmosphère mystérieuse, renforcée par l'ombre de la paroi rocheuse Jezerní stěna, haute de 300 mètres. Le lac fait partie de la réserve naturelle nationale des lacs Noir et du Diable. La légende raconte que le diable s'y est noyé en tentant de voler l'âme d'une jeune fille, son corps creusant ainsi le lac. Une curiosité géologique réside dans le fait que le lac du Diable appartient au bassin versant du Danube, tandis que le lac Noir voisin appartient à celui de l'Elbe. Un sentier de randonnée pittoresque relie les deux lacs et offre des panoramas spectaculaires.",
    },
