    name: { de: "Rejvíz-Moossee", hu: "Rejvízi-lápitó", ro: "Lacul de turbă Rejvíz", en: "Rejviz Moss Lake"},
    image: "/poi-images/czechrepublic-rejviz-lake-nature-v2.webp",
    coords: [17.301, 50.228],
