      es: ["La turbera alta más grande de Moravia", "Sendero educativo sobre tablas de madera", "Presencia de plantas carnívoras", "Altitud: 769 m sobre el nivel del mar"],
      pt: ["Maior turfeira alta da Morávia", "Trilho educativo em pranchas de madeira", "Ocorrência de plantas carnívoras", "Altitude: 769 m acima do nível do mar"],
