    imageHint: "Doupov Mountains volcanic landscape forest",
    image: "/poi-images/czechrepublic-doupov-mountains-nature-v2.webp",
    descriptionAdvanced: {
      de: "Das Duppauer Gebirge (Doupovské hory) ist ein erloschener Schichtvulkan und eines der größten Vulkangebirge in Mitteleuropa. Das Gebiet liegt im Westen Tschechiens und ist aufgrund seiner militärischen Nutzung als Truppenübungsplatz seit 1953 für die Öffentlichkeit größtenteils unzugänglich. Diese jahrzehntelange Isolation hat eine einzigartige, vom Menschen kaum beeinflusste Naturlandschaft bewahrt. Das Gebirge zeichnet sich durch ein sternförmiges Netz von Tälern aus, die vom zentralen Teil ausgehen. Die Hänge sind mit artenreichen Wäldern, Wiesen und Heiden bedeckt, die einen Lebensraum für viele seltene und bedrohte Tier- und Pflanzenarten bieten, darunter der Schwarzstorch und der Biber. Obwohl der größte Teil des Gebiets gesperrt ist, wurden in den letzten Jahren einige Randbereiche für Wanderer und Radfahrer geöffnet, die einen Einblick in diese wilde und unberührte Landschaft ermöglichen.",
      hu: "A Doupovi-hegység (Doupovské hory) egy kialudt rétegvulkán és Közép-Európa egyik legnagyobb vulkanikus hegysége. A terület Csehország nyugati részén fekszik, és 1953 óta katonai gyakorlótérként való használata miatt a nyilvánosság számára nagyrészt hozzáférhetetlen. Ez az évtizedes elszigeteltség egyedülálló, ember által alig befolyásolt természeti tájat őrzött meg. A hegységet a központi részből kiinduló, csillag alakú völgyhálózat jellemzi. A lejtőket fajgazdag erdők, rétek és puszták borítják, amelyek számos ritka és veszélyeztetett állat- és növényfajnak adnak otthont, köztük a fekete gólyának és a hódnak. Bár a terület nagy része le van zárva, az utóbbi években néhány peremterületet megnyitottak a túrázók és kerékpárosok előtt, amelyek bepillantást engednek ebbe a vad és érintetlen tájba.",
      ro: "Munții Doupov (Doupovské hory) sunt un stratovulcan stins și unul dintre cele mai mari lanțuri montane vulcanice din Europa Centrală. Zona este situată în vestul Cehiei și, din cauza utilizării sale militare ca teren de antrenament din 1953, este în mare parte inaccesibilă publicului. Această izolare de zeci de ani a conservat un peisaj natural unic, aproape neafectat de om. Munții sunt caracterizați de o rețea de văi în formă de stea, care pornesc din partea centrală. Versanții sunt acoperiți cu păduri bogate în specii, pajiști și lande, care oferă un habitat pentru multe specii rare și pe cale de dispariție de animale și plante, inclusiv barza neagră și castorul. Deși cea mai mare parte a zonei este închisă, în ultimii ani au fost deschise câteva zone marginale pentru drumeți și cicliști, care permit o incursiune în acest peisaj sălbatic și neatins.",
      en: "The Doupov Mountains (Doupovské hory) are an extinct stratovolcano and one of the largest volcanic mountain ranges in Central Europe. The area is located in the west of the Czech Republic and has been largely inaccessible to the public since 1953 due to its military use as a training area. This decades-long isolation has preserved a unique natural landscape that has been little influenced by humans. The mountains are characterized by a star-shaped network of valleys radiating from the central part. The slopes are covered with species-rich forests, meadows and heathland, which provide a habitat for many rare and endangered animal and plant species, including the black stork and the beaver. Although most of the area is closed, some peripheral areas have been opened up to hikers and cyclists in recent years, offering a glimpse into this wild and untouched landscape.",
      es: "Las Montañas de Doupov (Doupovské hory) son un estratovolcán extinguido y una de las áreas volcánicas más grandes de Europa Central. Situada en el oeste de la República Checa, la zona es en su mayor parte inaccesible al público desde 1953 debido a su uso militar como campo de entrenamiento. Este aislamiento de décadas ha preservado un paisaje natural único, apenas influenciado por el hombre. El macizo se caracteriza por una red de valles en forma de estrella que parten de la parte central. Las laderas están cubiertas de bosques, praderas y brezales ricos en especies, que sirven de hábitat para muchos animales y plantas raros y amenazados, como la cigüeña negra y el castor. Aunque la mayor parte del territorio está restringida, en los últimos años se han abierto algunas zonas periféricas a senderistas y ciclistas, permitiendo vislumbrar este paisaje salvaje e intacto.",
      pt: "As Montanhas Doupov (Doupovské hory) são um estratovulcão extinto e uma das maiores cadeias montanhosas vulcânicas da Europa Central. A área situa-se no oeste da República Checa e é, em grande parte, inacessível ao público desde 1953 devido ao seu uso militar como campo de treino. Este isolamento de décadas preservou uma paisagem natural única, mal influenciada pelo homem. A cordilheira caracteriza-se por uma rede de vales em forma de estrela que partem da parte central. As encostas estão cobertas por florestas, prados e charnecas ricos em espécies, que oferecem habitat para muitas espécies animais e vegetais raras e ameaçadas, incluindo a cegonha-preta e o castor. Embora a maior parte da área esteja fechada, nos últimos anos algumas áreas periféricas foram abertas a caminhantes e ciclistas, permitindo um vislumbre desta paisagem selvagem e intocada.",
      fr: "Les monts de Doupov (Doupovské hory) constituent un ancien stratovolcan et l'un des plus grands massifs volcaniques d'Europe centrale. Située à l'ouest de la Tchéquie, la zone est en grande partie fermée au public depuis 1953 en raison de son utilisation comme terrain d'entraînement militaire. Cet isolement de plusieurs décennies a préservé un paysage naturel unique, presque exempt d'influence humaine. Le massif se distingue par son réseau de vallées en étoile partant du centre. Les versants sont couverts de forêts, de prairies et de landes riches en biodiversité, offrant un habitat à de nombreuses espèces rares ou menacées, comme la cigogne noire et le castor. Bien que la majeure partie du territoire reste interdite, certaines zones périphériques ont été ouvertes ces dernières années aux randonneurs et cyclistes, offrant un aperçu de cette nature sauvage.",
    },
