    imageHint: "Luznice river meanders canoe landscape",
    descriptionAdvanced: {
      de: "Die Lužnice (Lainsitz) ist ein rechter Nebenfluss der Moldau, der in Österreich entspringt und durch Südböhmen fließt. Der Fluss ist besonders für seine zahlreichen Mäander und die malerische, gut erhaltene Auenlandschaft bekannt. Die Lužnice ist ein Paradies für Wassertouristen und gilt als einer der beliebtesten Flüsse für Kanu- und Bootsfahrten in Tschechien. Entlang ihres Laufs liegen historische Städte wie Třeboň und Tábor. Die Region um Třeboň ist berühmt für ihr ausgeklügeltes System von Fischteichen, das im Mittelalter angelegt wurde und heute als UNESCO-Biosphärenreservat geschützt ist. Der größte dieser Teiche, der Rožmberk, wird von der Lužnice gespeist. Der Fluss bietet Lebensraum für eine Vielzahl von Wasservögeln und Fischen. Der Name 'Lužnice' leitet sich vom altslawischen Wort 'luh' ab, was 'Auwald' oder 'Wiese' bedeutet und die Landschaft entlang des Flusses treffend beschreibt.",
      hu: "A Lužnice (németül Lainsitz) a Moldva jobb oldali mellékfolyója, amely Ausztriában ered és Dél-Csehországon folyik keresztül. A folyó különösen számos kanyarulatáról és festői, jó állapotban megőrzött árteréről ismert. A Lužnice a vízitúrázók paradicsoma, és Csehország egyik legnépszerűbb evezős folyójának számít. Útja mentén olyan történelmi városok fekszenek, mint Třeboň és Tábor. A Třeboň környéki régió híres a középkorban kialakított, bonyolult halastórendszeréről, amely ma UNESCO bioszféra-rezervátumként védett. A legnagyobb tó, a Rožmberk, a Lužnice vizével táplálkozik. A folyó számos vízimadárnak és halfajnak ad otthont. A 'Lužnice' név az ószláv 'luh' szóból származik, ami 'ártéri erdőt' vagy 'rétet' jelent, és találóan írja le a folyó menti tájat.",
      ro: "Lužnice (Lainsitz în germană) este un afluent de dreapta al Vltavei, care izvorăște din Austria și curge prin Boemia de Sud. Râul este deosebit de cunoscut pentru numeroasele sale meandre și peisajul pitoresc și bine conservat al luncii inundabile. Lužnice este un paradis pentru turiștii nautici și este considerat unul dintre cele mai populare râuri pentru canoe și plimbări cu barca din Cehia. De-a lungul cursului său se află orașe istorice precum Třeboň și Tábor. Regiunea din jurul Třebonului este renumită pentru sistemul său ingenios de iazuri piscicole, creat în Evul Mediu și protejat astăzi ca rezervație a biosferei UNESCO. Cel mai mare dintre aceste iazuri, Rožmberk, este alimentat de Lužnice. Râul oferă habitat pentru o varietate de păsări acvatice și pești. Numele 'Lužnice' derivă din vechiul cuvânt slav 'luh', care înseamnă 'pădure de luncă' sau 'pajiște', descriind cu acuratețe peisajul de-a lungul râului.",
      en: "The Lužnice (Lainsitz in German) is a right tributary of the Vltava that rises in Austria and flows through South Bohemia. The river is particularly known for its numerous meanders and the picturesque, well-preserved floodplain landscape. The Lužnice is a paradise for water tourists and is considered one of the most popular rivers for canoeing and boating in the Czech Republic. Along its course are historic towns such as Třeboň and Tábor. The region around Třeboň is famous for its ingenious system of fishponds, created in the Middle Ages and now protected as a UNESCO Biosphere Reserve. The largest of these ponds, the Rožmberk, is fed by the Lužnice. The river provides a habitat for a variety of water birds and fish. The name 'Lužnice' is derived from the Old Slavonic word 'luh', which means 'floodplain forest' or 'meadow', and aptly describes the landscape along the river.",
      es: "El Lužnice (Lainsitz) es un afluente derecho del Moldava que nace en Austria y fluye por el sur de Bohemia. El río es especialmente conocido por sus numerosos meandros y por el paisaje de llanura aluvial pintoresco y bien conservado que atraviesa. El Lužnice es un paraíso para los entusiastas de las actividades acuáticas y se considera uno de los ríos más populares para el piragüismo y los paseos en bote en la República Checa. A lo largo de su curso se encuentran ciudades históricas como Třeboň y Tábor. La región de Třeboň es famosa por su ingenioso sistema de estanques de peces, creado en la Edad Media y hoy protegido como Reserva de la Biosfera de la UNESCO. El mayor de estos estanques, el Rožmberk, es alimentado por el Lužnice. El río ofrece hábitat a una gran variedad de aves acuáticas y peces. El nombre deriva de la palabra eslava antigua 'luh', que significa 'bosque aluvial' o 'pradera'.",
      pt: "O Lužnice é um afluente da margem direita do Moldava, que nasce na Áustria e corre através da Boêmia do Sul. O rio é especialmente conhecido pelos seus inúmeros meandros e pela paisagem de várzea pitoresca e bem preservada. O Lužnice é um paraíso para os turistas náuticos e é considerado um dos rios mais populares para passeios de canoa e barco na República Checa. Ao longo do seu curso situam-se cidades históricas como Třeboň e Tábor. A região em redor de Třeboň é famosa pelo seu sistema sofisticado de tanques de peixes, criado na Idade Médica e hoje protegido como Reserva da Biosfera da UNESCO. O maior destes tanques, o Rožmberk, é alimentado pelo Lužnice. O rio oferece habitat para uma variedade de aves aquáticas e peixes. O nome 'Lužnice' deriva da palavra eslava antiga 'luh', que significa 'floresta de várzea' ou 'prado'.",
      fr: "La Lužnice est un affluent de la Vltava qui prend sa source en Autriche avant de traverser la Bohême du Sud. La rivière est particulièrement réputée pour ses nombreux méandres et ses paysages de plaines alluviales préservés. C'est un véritable paradis pour les amateurs de canoë et de kayak, figurant parmi les rivières les plus fréquentées du pays. Son cours traverse des cités historiques telles que Třeboň et Tábor. La région de Třeboň est célèbre pour son réseau complexe d'étangs de pisciculture, conçu au Moyen Âge et aujourd'hui classé réserve de biosphère par l'UNESCO. Le plus grand d'entre eux, l'étang Rožmberk, est alimenté par la Lužnice. La rivière constitue un habitat précieux pour de nombreuses espèces de poissons et d'oiseaux aquatiques. Son nom provient du vieux slave 'luh', désignant une forêt inondable ou une prairie humide.",
    },
